class WeatherSystem:

    def __init__(self, city) -> None:
        self.temperature = None
        self.weather = None
        self.city = city
        self.weather_list = {}

    def query(self, weather_list, tmp_units='celsius'):
        if self.city not in weather_list:
            return (None, None)
        weather_info = weather_list[self.city]
        temperature = weather_info['temperature']
        weather = weather_info['weather']
        if 'temperature units' not in weather_info:
            raise KeyError("Missing 'temperature units' key in weather information.")
        if weather_info['temperature units'] == 'celsius':
            if tmp_units == 'fahrenheit':
                temperature = self.celsius_to_fahrenheit(temperature)
            elif tmp_units != 'celsius':
                raise ValueError(f'Invalid temperature units: {tmp_units}')
        elif weather_info['temperature units'] == 'fahrenheit':
            if tmp_units == 'celsius':
                temperature = self.fahrenheit_to_celsius(temperature)
            elif tmp_units != 'fahrenheit':
                raise ValueError(f'Invalid temperature units: {tmp_units}')
        else:
            raise ValueError(f'Invalid temperature units: {weather_info['temperature units']}')
        return (temperature, weather)

    def set_city(self, city):
        """Set the city of the weather system.
        :param city: the city to set, str.
        :return: None
        """
        if not isinstance(city, str):
            raise TypeError('City must be a string')
        self.city = city

    def celsius_to_fahrenheit(self):
        """Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, float.
        """
        return self.temperature * 9 / 5 + 32

    def fahrenheit_to_celsius(self):
        """Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, float.
        """
        if self.temperature is None:
            raise ValueError('Temperature not set')
        if self.temperature < -459.67:
            raise ValueError('Temperature below absolute zero')
        return (self.temperature - 32) * 5.0 / 9.0

